 if(name.includes('Metal_Corrogated')||name==='[Color M09]1'){const frame=m.clone();frame.map=null;frame.color.set('#252a28');frame.metalness=.45;frame.roughness=.65;o.material=frame;frames.push(frame);finishes.push(frame);return;}
